import { XMLParser } from 'fast-xml-parser'
import { fileUriToPath } from './fileUri'

/**
 * Reads an existing rekordbox.xml (e.g. one exported by rekordbox itself,
 * or previously generated by this app) back into a plain structure. This is
 * a read-only import path — unlike the Serato/VirtualDJ writers, we never
 * patch this file in place, so a generic parser is fine here.
 */

export interface ImportedRekordboxCue {
  name?: string
  positionSeconds: number
  num: number
}

export interface ImportedRekordboxLoop {
  name?: string
  startSeconds: number
  endSeconds: number
  num: number
}

export interface ImportedRekordboxTrack {
  id: string
  filePath: string
  name: string
  artist: string
  album?: string
  averageBpm?: number
  cues: ImportedRekordboxCue[]
  loops: ImportedRekordboxLoop[]
}

const parser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: '@_' })

function asArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) return []
  return Array.isArray(value) ? value : [value]
}

export function parseRekordboxXml(xml: string): ImportedRekordboxTrack[] {
  const doc = parser.parse(xml)
  const collection = doc?.DJ_PLAYLISTS?.COLLECTION
  const rawTracks = asArray(collection?.TRACK)

  return rawTracks.map((raw) => {
    const marks = asArray(raw.POSITION_MARK)
    const cues: ImportedRekordboxCue[] = marks
      .filter((m) => Number(m['@_Type']) === 0)
      .map((m) => ({
        name: m['@_Name'] || undefined,
        positionSeconds: Number(m['@_Start']),
        num: Number(m['@_Num'])
      }))
    const loops: ImportedRekordboxLoop[] = marks
      .filter((m) => Number(m['@_Type']) === 4)
      .map((m) => ({
        name: m['@_Name'] || undefined,
        startSeconds: Number(m['@_Start']),
        endSeconds: Number(m['@_End']),
        num: Number(m['@_Num'])
      }))

    return {
      id: String(raw['@_TrackID']),
      filePath: fileUriToPath(raw['@_Location']),
      name: raw['@_Name'],
      artist: raw['@_Artist'],
      album: raw['@_Album'] || undefined,
      averageBpm: raw['@_AverageBpm'] !== undefined ? Number(raw['@_AverageBpm']) : undefined,
      cues,
      loops
    }
  })
}
